const raw = $input.first().json.output;

// 1) если агент вернул строку — чистим её
let cleaned = typeof raw === 'string' ? raw.trim() : raw;

// 2) если это строка, убираем markdown-обёртку ```json ... ```
if (typeof cleaned === 'string') {
  cleaned = cleaned
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

// 3) если в строке есть лишний текст до/после JSON — вытаскиваем только объект
if (typeof cleaned === 'string') {
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    cleaned = cleaned.slice(start, end + 1);
  }
}

// 4) парсим JSON
const data = typeof cleaned === 'string' ? JSON.parse(cleaned) : cleaned;

// 5) возвращаем разложенные поля
return [
  {
    json: {
      name: data.name || '',
      ingredients: data.ingredients || '',
      steps_text: data.steps_text || '',

      prompt_ingredients: data.prompt_ingredients || '',
      prompt_step1: data.prompt_step1 || '',
      prompt_step2: data.prompt_step2 || '',
      prompt_step3: data.prompt_step3 || '',
      prompt_step4: data.prompt_step4 || '',
      prompt_final: data.prompt_final || ''
    }
  }
];

